for unit,topics in [(3,topics3),(4,topics4)]:
    qs=data[f'unit{unit}']; headings=dict(topics)
    parts.append(f'<h2 id="unit{unit}">Unit {unit} · {len(qs)} questions</h2>')
    for item in qs:
        n=item['n']; answer=item['answer']
        if n in headings: parts.append(f'<h3>{esc(headings[n])}</h3>')
        parts.append(f'<article class="question" id="u{unit}q{n}"><h4>{n}. {esc(item["q"])}</h4><ol class="options" type="A">')
        parts.extend(f'<li>{esc(o)}</li>' for o in item['options'])
        parts.append('</ol>')
        if answer=='N': answer_text='No valid listed option — see correction below.'
        else: answer_text='; '.join(f'{a}. {item["options"][ord(a)-65]}' for a in answer.split(','))
        parts.append(f'<div class="answer"><b>Answer:</b> {esc(answer_text)}</div>')
        if item['note']: parts.append(f'<div class="note">{esc(item["note"])}</div>')
        parts.append('</article>')
parts.append('<h2 id="keys">Quick answer keys</h2><p>N = no valid listed option; see the correction in the question. An asterisk marks a clarification or source issue.</p>')
for unit in (3,4):
    parts.append(f'<h3>Unit {unit}</h3><div class="key">')
    for q in data[f'unit{unit}']:
        parts.append(f'<a href="#u{unit}q{q["n"]}">{q["n"]}: {q["answer"]}{"*" if q["note"] else ""}</a>')
    parts.append('</div>')
parts.append('<p class="meta">Source: authenticated Maths course materials at <a href="https://www.pesuacademy.com/Academy/">PESU Academy</a>. Account credentials and personal profile information are excluded.</p></html>')
(out/'maths-unit-3-4-mcqs.html').write_text('\n'.join(parts))
